refsection.programlisting:
// Define parameters
m = 21       // Length of the window
a = 0.4      // Width control (higher a = narrower window)
// Generate Gaussian window
w = gaussian(m, a)
// Plot the window
x = linspace(-(m-1)/2, (m-1)/2, m);
plot(x, w, '-o');
title('Gaussian Window');
xlabel('Samples');
ylabel('Amplitude');
xgrid;
